import { TableMetadata } from '../types';
import { toPascalCase } from '../utils/naming';

export function generateSito(meta: TableMetadata): string {
  const className = toPascalCase(meta.name);
  const tableName = meta.name;

  return `/**
 * src/api/sito/${tableName}.sito.ts
 * ---------------------------------------------------------------
 * SITO facade for ${className}: a single entrypoint that ties together
 * the service (S), interface (I), transformer/mapper (T), and
 * operation (O).
 *
 * AUTO-GENERATED by hexagonal-ts-generator.
 *
 * Copyright 2025 β ORI Inc. Canada. All Rights Reserved.
 */
import { ${className}CreateDTO, ${className}UpdateDTO, ${className}ResponseDTO } from '../dtos/${tableName}.dto';
import { ${className}Mapper } from '../mappers/${tableName}.mapper';
import { ${className}Service } from '../../application/services/${tableName}/${tableName}.service';
import { ${className} } from '../../domain/${tableName}/${tableName}.entity';
import { logger } from '../../shared/utils/logger';

/**
 * A single instance of the service is shared across the process.
 * (TypeORM DataSource is internally pooled, so we don't need to spin
 * up a service per request.)
 */
const ${tableName}Service = new ${className}Service();

/**
 * The SITO object — every operation the API layer needs for ${className}.
 * Controllers should import this object instead of the service directly.
 */
export const ${tableName}Sito = {
  service: ${tableName}Service,
  mapper: ${className}Mapper,

  async create(dto: ${className}CreateDTO): Promise<${className}ResponseDTO> {
    logger.info(\`SITO: creating ${className}\`);
    const entity = await ${tableName}Service.create(${className}Mapper.fromCreate(dto));
    return ${className}Mapper.toResponse(entity);
  },

  async update(id: string | number, dto: ${className}UpdateDTO): Promise<${className}ResponseDTO | null> {
    logger.info(\`SITO: updating ${className} id=\${id}\`);
    const entity = await ${tableName}Service.update(id, ${className}Mapper.fromUpdate(dto));
    if (!entity) return null;
    return ${className}Mapper.toResponse(entity);
  },

  async getById(id: string | number): Promise<${className}ResponseDTO | null> {
    const entity = await ${tableName}Service.getById(id);
    if (!entity) return null;
    return ${className}Mapper.toResponse(entity);
  },

  async list(skip = 0, take = 100): Promise<${className}ResponseDTO[]> {
    const entities = await ${tableName}Service.list(skip, take);
    return entities.map(${className}Mapper.toResponse);
  },

  async count(): Promise<number> {
    return ${tableName}Service.count();
  },

  async remove(id: string | number): Promise<boolean> {
    return ${tableName}Service.delete(id);
  },
};

export type ${className}Sito = typeof ${tableName}Sito;
`;
}
